mapper.select:
select prp.id,pp.product_name,prp.product_type_upgraded,psc.customer_name,DATE_FORMAT(prp.create_time, '%Y-%m-%d %H:%i:%s') AS createTime
from pr_reservoir_project prp
inner join pr_super_customer psc ON prp.superCustomer_Id=psc.id
inner join pr_product pp ON prp.product_id=pp.id
WHERE 1=1

        AND prp.product_type = #{productType}



        AND prp.upgradedProjectStage = #{upgradedProjectStage}




            AND prp.create_time BETWEEN #{startTime} AND #{endTime}


            AND prp.create_time >= #{startTime}


            AND prp.create_time < #{endTime}



Limit #{start},#{size}

select count(*)
from pr_reservoir_project prp
inner join pr_super_customer psc ON prp.superCustomer_Id=psc.id
inner join pr_product pp ON prp.product_id=pp.id
WHERE 1=1

    AND prp.product_type = #{productType}



    AND prp.upgradedProjectStage = #{upgradedProjectStage}




        AND prp.create_time BETWEEN #{startTime} AND #{endTime}


        AND prp.create_time >= #{startTime}


        AND prp.create_time < #{endTime}
